from dataclasses import dataclass, replace

@dataclass(frozen=True, slots=True)
class Settings:
    host: str = "db"
    port: int = 8080

def with_port(s: Settings, p: int) -> Settings:
    return replace(s, port=p)     # new value; nothing shared is mutated

